// Merge current + previous hour results and compute spike ratio.
const current = $node['Current hour stats'].json.results || $node['Current hour stats'].json;
const previous = $node['Previous hour baseline'].json.results || $node['Previous hour baseline'].json;
const currentViews = (current.pageviews && current.pageviews.value) || current.pageviews || 0;
const previousViews = (previous.pageviews && previous.pageviews.value) || previous.pageviews || 0;
const spikeMultiplier = $node['SET_DEFAULTS'].json['spike_multiplier'];
const minViews = $node['SET_DEFAULTS'].json['min_hourly_views_for_alert'];

const ratio = previousViews > 0 ? (currentViews / previousViews) : (currentViews > 0 ? Infinity : 0);
const isSpike = currentViews >= minViews && ratio >= spikeMultiplier;

return [{
  json: {
    current_views: currentViews,
    previous_views: previousViews,
    ratio: Number(ratio.toFixed(2)),
    is_spike: isSpike,
    spike_multiplier: spikeMultiplier,
    min_views_threshold: minViews,
    checked_at: new Date().toISOString()
  }
}];

